--keel:notx
-- Rollup detention_policy_daily of detention_occurrences, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'detention_policy_daily';
DELETE FROM keel_rollup_dirty WHERE rollup = 'detention_policy_daily';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"detention_policy_daily"') AND obj_description(oid, 'pg_class') = 'keel rollup detention_policy_daily of detention_occurrences') THEN
        DROP TABLE "detention_policy_daily";
    END IF;
END
$keel$;
CREATE TABLE "detention_policy_daily" AS SELECT s."business_unit_id" AS "business_unit_id", s."organization_id" AS "organization_id", date_trunc('day', to_timestamp(s."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = s."organization_id"), 'UTC'))) AS "bucket", s."location_id" AS "location_id", s."detention_policy_id" AS "detention_policy_id", count(*) AS "row_count", min(s."clock_start_at") AS "clock_start_at_min" FROM "detention_occurrences" s GROUP BY 1, 2, 3, 4, 5 WITH NO DATA;
COMMENT ON TABLE "detention_policy_daily" IS 'keel rollup detention_policy_daily of detention_occurrences';
ALTER TABLE "detention_policy_daily" ALTER COLUMN "business_unit_id" SET NOT NULL, ALTER COLUMN "organization_id" SET NOT NULL;
CREATE UNIQUE INDEX "detention_policy_daily_key" ON "detention_policy_daily" ("business_unit_id", "organization_id", "bucket", "location_id", "detention_policy_id") NULLS NOT DISTINCT;
CREATE INDEX "detention_policy_daily_by_location_id" ON "detention_policy_daily" ("business_unit_id", "organization_id", "location_id", "bucket");
CREATE OR REPLACE FUNCTION keel_rollup_detention_policy_daily() RETURNS trigger LANGUAGE plpgsql AS $keel$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_policy_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_policy_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_policy_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "location_id", "detention_policy_id", "clock_start_at", "is_open" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "location_id", "detention_policy_id", "clock_start_at", "is_open" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "location_id", "detention_policy_id", "clock_start_at", "is_open" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "location_id", "detention_policy_id", "clock_start_at", "is_open" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_detention_policy_daily_insert" AFTER INSERT ON "detention_occurrences" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_policy_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_policy_daily_update" AFTER UPDATE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_policy_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_policy_daily_delete" AFTER DELETE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_policy_daily();
